import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with an extra property through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    let received: Record<string, unknown> | null = null;
    registry.register(
      {
        name: 'lookup',
        description: 'A tool',
        inputSchema: {type: 'object', properties: {name: {type: 'string'}}, required: ['name']},
      },
      async input => {
        received = input;
        return 'ok';
      }
    );

    const response = await registry.execute('lookup', {name: 'Alice', extra: 42});

    expect({result: response.result, received}).toEqual({result: 'ok', received: {name: 'Alice', extra: 42}});
  });
});
